/**
 * Characterization tests: they pin down the SQL currently generated by each client,
 * so the architectural refactor can be verified to be behavior-preserving.
 *
 * If a snapshot changes, the diff must be intentional and justified in the PR.
 */
import { describe, expect, it } from 'vitest';

import { FirebirdSQLClient } from '../../../src/main/libs/clients/FirebirdSQLClient';
import { MySQLClient } from '../../../src/main/libs/clients/MySQLClient';
import { PostgreSQLClient } from '../../../src/main/libs/clients/PostgreSQLClient';
import { SQLiteClient } from '../../../src/main/libs/clients/SQLiteClient';
import { captureRaw } from '../helpers/captureSql';
import { buildFixtures, engineTypes } from './fixtures';

type Fixtures = ReturnType<typeof buildFixtures>;
// Clients don't share a typed contract yet (see refactor plan, phase 2)
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type AnyClient = any;

const engines = [
   { name: 'mysql', create: () => new MySQLClient({ client: 'mysql', uid: 'test', params: {} as never }), types: engineTypes.mysql },
   { name: 'maria', create: () => new MySQLClient({ client: 'maria', uid: 'test', params: {} as never }), types: engineTypes.mysql },
   { name: 'pg', create: () => new PostgreSQLClient({ client: 'pg', uid: 'test', params: {} as never }), types: engineTypes.pg },
   { name: 'sqlite', create: () => new SQLiteClient({ client: 'sqlite', uid: 'test', params: {} as never }), types: engineTypes.sqlite },
   { name: 'firebird', create: () => new FirebirdSQLClient({ client: 'firebird', uid: 'test', params: {} as never }), types: engineTypes.firebird }
] as const;

interface Operation {
   /** Client method that must exist for the case to run */
   method: string;
   run: (c: AnyClient, f: Fixtures) => Promise<unknown>;
}

const operations: Record<string, Operation> = {
   // Query builder
   'select builder': {
      method: 'select',
      run: (c, f) => c.select('id', 'name').schema(f.schema).from(f.table)
         .where('price > 10', 'stock > 0').orderBy({ name: 'ASC' }).limit(50).offset(100).run({ schema: f.schema })
   },
   'update builder': {
      method: 'select',
      run: (c, f) => c.update({ name: '\'foo\'' }, { price: '12.5' }).schema(f.schema).from(f.table).where({ id: '= 1' }).limit(1).run()
   },
   'insert builder': {
      method: 'select',
      run: (c, f) => c.schema(f.schema).into(f.table).insert([{ id: 1, name: '\'a\'' }, { id: 2, name: '\'b\'' }]).run()
   },
   'delete builder': {
      method: 'select',
      run: (c, f) => c.schema(f.schema).delete(f.table).where({ id: '= 1' }).run()
   },

   // Schemas
   createSchema: { method: 'createSchema', run: c => c.createSchema({ name: 'new_schema', collation: 'utf8mb4_general_ci' }) },
   alterSchema: { method: 'alterSchema', run: c => c.alterSchema({ name: 'new_schema', collation: 'utf8mb4_bin' }) },
   dropSchema: { method: 'dropSchema', run: c => c.dropSchema({ database: 'new_schema' }) },

   // Tables
   createTable: { method: 'createTable', run: (c, f) => c.createTable(f.createTable) },
   alterTable: { method: 'alterTable', run: (c, f) => c.alterTable(f.alterTable) },
   duplicateTable: { method: 'duplicateTable', run: (c, f) => c.duplicateTable({ schema: f.schema, table: f.table }) },
   truncateTable: { method: 'truncateTable', run: (c, f) => c.truncateTable({ schema: f.schema, table: f.table, force: false }) },
   'truncateTable force': { method: 'truncateTable', run: (c, f) => c.truncateTable({ schema: f.schema, table: f.table, force: true }) },
   dropTable: { method: 'dropTable', run: (c, f) => c.dropTable({ schema: f.schema, table: f.table }) },

   // Views
   createView: { method: 'createView', run: (c, f) => c.createView(f.view) },
   alterView: { method: 'alterView', run: (c, f) => c.alterView({ view: f.view }) },
   dropView: { method: 'dropView', run: (c, f) => c.dropView({ schema: f.schema, view: f.view.name }) },
   createMaterializedView: { method: 'createMaterializedView', run: (c, f) => c.createMaterializedView(f.view) },
   alterMaterializedView: { method: 'alterMaterializedView', run: (c, f) => c.alterMaterializedView({ view: f.view }) },
   dropMaterializedView: { method: 'dropMaterializedView', run: (c, f) => c.dropMaterializedView({ schema: f.schema, view: f.view.name }) },

   // Triggers
   createTrigger: { method: 'createTrigger', run: (c, f) => c.createTrigger(f.trigger) },
   alterTrigger: { method: 'alterTrigger', run: (c, f) => c.alterTrigger({ trigger: f.trigger }) },
   dropTrigger: { method: 'dropTrigger', run: (c, f) => c.dropTrigger({ schema: f.schema, trigger: f.trigger.name }) },
   enableTrigger: { method: 'enableTrigger', run: (c, f) => c.enableTrigger({ schema: f.schema, trigger: f.trigger.name }) },
   disableTrigger: { method: 'disableTrigger', run: (c, f) => c.disableTrigger({ schema: f.schema, trigger: f.trigger.name }) },

   // Routines
   createRoutine: { method: 'createRoutine', run: (c, f) => c.createRoutine(f.routine) },
   alterRoutine: { method: 'alterRoutine', run: (c, f) => c.alterRoutine({ routine: f.routine }) },
   dropRoutine: { method: 'dropRoutine', run: (c, f) => c.dropRoutine({ schema: f.schema, routine: f.routine.name }) },

   // Functions
   createFunction: { method: 'createFunction', run: (c, f) => c.createFunction(f.func) },
   alterFunction: { method: 'alterFunction', run: (c, f) => c.alterFunction({ func: f.func }) },
   dropFunction: { method: 'dropFunction', run: (c, f) => c.dropFunction({ schema: f.schema, func: f.func.name }) },
   createTriggerFunction: { method: 'createTriggerFunction', run: (c, f) => c.createTriggerFunction({ ...f.func, name: 'trg_fn' }) },
   alterTriggerFunction: { method: 'alterTriggerFunction', run: (c, f) => c.alterTriggerFunction({ func: { ...f.func, name: 'trg_fn' } }) },

   // Events
   createEvent: { method: 'createEvent', run: (c, f) => c.createEvent(f.event) },
   alterEvent: { method: 'alterEvent', run: (c, f) => c.alterEvent({ scheduler: f.event }) },
   dropEvent: { method: 'dropEvent', run: (c, f) => c.dropEvent({ schema: f.schema, scheduler: f.event.name }) },
   enableEvent: { method: 'enableEvent', run: (c, f) => c.enableEvent({ schema: f.schema, scheduler: f.event.name }) },
   disableEvent: { method: 'disableEvent', run: (c, f) => c.disableEvent({ schema: f.schema, scheduler: f.event.name }) },

   // Processes
   killProcess: { method: 'killProcess', run: c => c.killProcess(42) }
};

/** Canned rows for queries that read data before generating DDL */
const responder = (sql: string) => {
   if (/type\s*=\s*'trigger'/i.test(sql)) { // SQLite alterTable reads table triggers
      return [{
         name: 'products_bi',
         sql: 'CREATE TRIGGER `products_bi` BEFORE INSERT ON `products` BEGIN SELECT 1; END'
      }];
   }
   return undefined;
};

for (const { name, create, types } of engines) {
   describe(`${name} client SQL generation`, () => {
      const fixtures = buildFixtures(types);
      const probe = create() as AnyClient;

      for (const [label, op] of Object.entries(operations)) {
         // Skip methods the engine doesn't implement (optional capabilities)
         const implemented = typeof probe[op.method] === 'function';

         it.skipIf(!implemented)(label, async () => {
            const client = create() as AnyClient;
            const capture = captureRaw(client, responder);
            let error: string | undefined;

            try {
               await op.run(client, fixtures);
            }
            catch (err) {
               error = String(err);
            }

            expect({ queries: capture.queries, ...(error ? { error } : {}) }).toMatchSnapshot();
         });
      }
   });
}
